import os
import tomllib
from copy import deepcopy
from typing import Any


class ConfigError(Exception):
    pass


def _coerce(value: str, expected_type: type) -> Any:
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(f"invalid int for {value}")
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(f"invalid float for {value}")
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "yes", "1"):
            return True
        if lower in ("false", "no", "0"):
            return False
        raise ConfigError(f"invalid bool for {value}")
    if expected_type is str:
        return value
    raise ConfigError(f"unknown type {expected_type}")


def _env_key(prefix: str, path: list[str]) -> str:
    return "__".join(prefix + "".join(k.upper() for k in path))


def _merge(d: dict, updates: dict) -> dict:
    for k, v in updates.items():
        if k in d and isinstance(d[k], dict) and isinstance(v, dict):
            _merge(d[k], v)
        else:
            d[k] = v
    return d


def load(defaults: dict, toml_path: str | None = None, prefix: str = "APP", env: dict | None = None) -> dict:
    cfg = deepcopy(defaults)
    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                toml_cfg = tomllib.load(f)
            cfg = _merge(cfg, toml_cfg)
