import os
import pytest
import envcfg


class TestPrecedence:
    def test_defaults_only(self):
        cfg = envcfg.load({"a": 1})
        assert cfg == {"a": 1}

    def test_toml_over_defaults(self):
        cfg = envcfg.load({"a": 1}, toml_path="test.toml")
        assert cfg == {"a": 2}

    def test_env_over_toml(self):
        cfg = envcfg.load({"a": 1}, toml_path="test.toml", env={"APP__A": "3"})
        assert cfg == {"a": 3}

    def test_env_over_defaults_no_toml(self):
        cfg = envcfg.load({"a": 1}, env={"APP__A": "3"})
        assert cfg == {"a": 3}


class TestNested:
    def test_nested_defaults(self):
        cfg = envcfg.load({"server": {"port": 80}})
        assert cfg == {"server": {"port": 80}}

    def test_nested_toml(self):
        cfg = envcfg.load({"server": {"port": 80}}, toml_path="test.toml")
        assert cfg == {"server": {"port": 8080}}

    def test_nested_env(self):
        cfg = envcfg.load({"server": {"port": 80}}, env={"APP__SERVER__PORT": "9000"})
        assert cfg == {"server": {"port": 9000}}

    def test_nested_env_over_toml(self):
        cfg = envcfg.load({"server": {"port": 80}}, toml_path="test.toml", env={"APP__SERVER__PORT": "9000"})
        assert cfg == {"server": {"port": 9000}}


